input.command:
$all = Get-CimInstance Win32_Process; $byId = @{}; $all | % { $byId[$_.ProcessId] = $_ }
$all | ? Name -eq 'EXCEL.EXE' | Select ProcessId, CreationDate, CommandLine | Format-List | Out-String -Width 250
$all | ? Name -like 'claude*' | % { $p = $byId[$_.ParentProcessId]; [pscustomobject]@{Id=$_.ProcessId; MB=[int]($_.WorkingSetSize/1MB); Started=$_.CreationDate.ToString('MM-dd HH:mm'); Parent= if($p){"$($p.Name)($($p.ProcessId))"}else{"gone($($_.ParentProcessId))"}; Cmd=($_.CommandLine -replace '^.*?claude(\.exe)?"?\s*','').Substring(0, [Math]::Min(90, ($_.CommandLine -replace '^.*?claude(\.exe)?"?\s*','').Length))} } | Sort Started | Format-Table -AutoSize | Out-String -Width 250

